import type { JSX } from "preact";
import { useEffect, useState } from "preact/hooks";
import { findWords } from "./findWords";
import { Game } from "./Game.js";
import { generateLetters } from "./generateLetters";
import { readVocabulary } from "./readVocabulary";
import type { Letter, Word } from "./types";

interface GameContext {
    letters: Letter[];
    words: Word[];
}

export function App(): JSX.Element {
    const [numLetters, setNumLetters] = useState(6);
    const [includeUnfamiliarWords, setIncludeUnfamiliarWords] = useState(false);
    const [gameContext, setGameContext] = useState<GameContext>();
    const [errorMessage, setErrorMessage] = useState<string>();

    useEffect(() => {
        readVocabulary().catch((error: unknown) => {
            setErrorMessage(
                error instanceof Error
                    ? error.message
                    : "Failed to preload vocabulary.",
            );
        });
    }, []);

    const exitGame = () => {
        setGameContext(undefined);
    };

    if (gameContext != null) {
        return (
            <Game
                letters={gameContext.letters}
                words={gameContext.words}
                exitGame={exitGame}
            />
        );
    }

    const generateGameContext = async () => {
        setErrorMessage(undefined);
        const vocabulary = await readVocabulary();
        const letters = generateLetters(
            numLetters,
            includeUnfamiliarWords,
            vocabulary,
        );
        const words = findWords(letters, includeUnfamiliarWords, vocabulary);
        const lettersWithId = letters.map((letter, index) => ({
            id: `${letter}${index}`,
            letter,
        }));
        setGameContext({ letters: lettersWithId, words });
    };

    return (
        <>
            <h1>Wordplay</h1>

            <table>
                <tbody>
                    <tr>
                        <td>Number of letters</td>
                        <td>
                            <input
                                type="number"
                                min={3}
                                step={1}
                                className="form-control"
                                value={numLetters}
                                onChange={(e) =>
                                    setNumLetters(Number(e.currentTarget.value))
                                }
                            />
                        </td>
                    </tr>

                    <tr>
                        <td className="pe-3">Include unfamiliar words</td>
                        <td>
                            <input
                                type="checkbox"
                                className="form-check-input"
                                checked={includeUnfamiliarWords}
                                onChange={(e) =>
                                    setIncludeUnfamiliarWords(
                                        e.currentTarget.checked,
                                    )
                                }
                            />
                        </td>
                    </tr>

                    <tr>
                        <td />
                        <td>
                            <button
                                type="button"
                                className="btn btn-primary mt-3"
                                onClick={() => {
                                    generateGameContext().catch(
                                        (error: unknown) => {
                                            setErrorMessage(
                                                error instanceof Error
                                                    ? error.message
                                                    : "Could not start a game. Please try again.",
                                            );
                                        },
                                    );
                                }}
                            >
                                Start
                            </button>
                        </td>
                    </tr>
                </tbody>
            </table>

            {errorMessage != null && (
                <p className="text-danger mt-3" role="alert">
                    {errorMessage}
                </p>
            )}
        </>
    );
}
